package com.example

/**
 * 10 ශ්‍රේණිය ඉතිහාසය - කාණ්ඩ 5 සිට 10 දක්වා (120 unique cards).
 * 100% curriculum-aligned with official Sri Lankan O/L Grade 10 History Syllabus.
 */
object FlashcardBankHistoryGrade10SetsPart1 {

  fun getCard(setNum: Int, cardNum: Int): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      5 -> set5Pandukabhaya[(c - 1) % 20]
      6 -> set6Mahindagamanaya[(c - 1) % 20]
      7 -> set7Dutugemunu[(c - 1) % 20]
      8 -> set8Valagamba[(c - 1) % 20]
      9 -> set9IrrigationMahasenDhatusena[(c - 1) % 20]
      10 -> set10PolonnaruwaDawn[(c - 1) % 20]
      else -> null
    }
  }

